function state():Grid2dSnapshot{return{schema:fixture.schema,seed:BigInt(fixture.seed),width:fixture.width,height:fixture.height,cellWidth:bits(fixture.cellWidthBits),cellHeight:bits(fixture.cellHeightBits),periodicX:fixture.periodicX,periodicY:fixture.periodicY,tiles:fixture.tiles.map(t=>{const m=t.media;let media:WfcTileMedia2d;if(m.kind==='bitmap')media={kind:'bitmap',width:m.width!,height:m.height!,palette:m.palette!,pixels:m.pixels!};else if(m.kind==='image')media={kind:'image',child:{childId:m.childId!,target:m.target!}};else media={kind:'vector',paths:m.paths!.map(p=>({strokeWidth:bits(p.strokeWidthBits),...(p.fill?{fill:p.fill}:{}),...(p.stroke?{stroke:p.stroke}:{}),segments:p.segments.map((s):WfcPathSegment=>{switch(s.kind){case'close':return{kind:'close'};case'moveTo':return{kind:'moveTo',to:point(s.toBits!)};case'lineTo':return{kind:'lineTo',to:point(s.toBits!)};case'quadTo':return{kind:'quadTo',to:point(s.toBits!),ctrl:point(s.ctrlBits!)};case'cubicTo':return{kind:'cubicTo',to:point(s.toBits!),ctrl1:point(s.ctrl1Bits!),ctrl2:point(s.ctrl2Bits!)};default:throw Error('fixture command');}})}))};return{id:t.id,...(t.label===undefined?{}:{label:t.label}),weight:bits(t.weightBits),media};}),rules:[{id:'adjacency',tileAId:'bitmap',tileBId:'vector 🧬',direction:'BOTTOM',allowed:false}],pinned:fixture.pinned,masked:fixture.masked};}
test('grid2d typed media, path words, optional colors and independent SQLite edit',async()=>{const s=state(),d=await grid2dSnapshotToSqliteDatabase(s),bytes=await exportSqliteDatabase(d),restored=await grid2dSnapshotFromSqliteDatabase(await importSqliteDatabase(bytes));expect(restored).toEqual(s);const db=Database.deserialize(bytes);expect(db.query('PRAGMA integrity_check').get()).toEqual({integrity_check:'ok'});expect(db.query('PRAGMA foreign_key_check').all()).toEqual([]);expect(db.query('SELECT kind FROM wfc_grid2d_segment ORDER BY ordinal').all()).toEqual(['moveTo','lineTo','quadTo','cubicTo','close'].map(kind=>({kind})));expect(db.query('SELECT a.authored_id AS a,b.authored_id AS b,direction FROM wfc_grid2d_rule JOIN wfc_grid2d_tile a ON tile_a_id=a.authored_id JOIN wfc_grid2d_tile b ON tile_b_id=b.authored_id').get()).toEqual({a:'bitmap',b:'vector 🧬',direction:'BOTTOM'});db.query("UPDATE wfc_grid2d_path_color SET red=7 WHERE role='stroke'").run();const edited=await grid2dSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()));const media=edited.tiles[1]!.media;if(media.kind!=='vector')throw Error('media');expect(media.paths[0]!.stroke!.r).toBe(7);db.close();const schema=new Database(':memory:');schema.exec(WFC_GRID2D_SQLITE_SCHEMA);expect(schema.query('SELECT name,sql FROM sqlite_schema ORDER BY name').all()).toEqual(d.tables.map(t=>({name:t.name,sql:t.sql})).sort((a,b)=>a.name.localeCompare(b.name)));schema.close();});
test('grid2d malformed ownership, scalar shape, width and admission',async()=>{const d=await grid2dSnapshotToSqliteDatabase(state());for(let i=0;i<7;i++){const m={tables:d.tables.map(t=>({...t,rows:t.rows.map(r=>({...r,values:[...r.values]}))}))},table=(name:string)=>m.tables.find(t=>t.name===name)!;switch(i){case 0:table('wfc_grid2d_rule').rows[0]!.values[4]=999n;break;case 1:table('wfc_grid2d_segment').rows[0]!.values[2]=99n;break;case 2:table('wfc_grid2d_path_color').rows[0]!.values[2]='unknown';break;case 3:table('wfc_grid2d_palette').rows[0]!.values[3]=-1n;break;case 4:table('wfc_grid2d_segment').rows[4]!.values[4]=1;break;case 5:table('wfc_grid2d_image').rows=[];break;default:table('wfc_grid2d_document').rows[0]!.values[9]=1n;}await expect(grid2dSnapshotFromSqliteDatabase(m)).rejects.toThrow();}const cancel=new AbortController();await expect(grid2dSnapshotToSqliteDatabase(state(),{signal:cancel.signal,onProgress:()=>cancel.abort()})).rejects.toThrow();await expect(grid2dSnapshotFromSqliteDatabase(d,{maxValueBytes:4})).rejects.toThrow();});

